layout.css.text:
/* Keep the tool in the opening viewport on common portrait screens.
   Very short landscape windows can scroll; the game has no deadline. */
.game {
  width: min(100%, calc((100svh - 350px) * .580645));
  min-width: min(240px, 100%);
  margin-inline: auto;
}

.stage { container-type: inline-size; }
.balloon-body {
  padding: 4cqw 4.5cqw;
  transform: scale(calc(.35 + var(--air) * .65));
  animation: inflate .45s ease-out;
}
.balloon-small .balloon-body { padding: 3.8cqw; }
.balloon-topline { font-size: clamp(8px, 2.7cqw, 10px); }
.badge { font-size: clamp(8px, 2.5cqw, 10px); }
.balloon h2 {
  font-size: 7.2cqw;
  margin-top: 3.2cqw;
  margin-bottom: 1.5cqw;
  letter-spacing: -.35cqw;
}
.balloon-small h2 { font-size: 6.5cqw; margin-top: 2.7cqw; }
.balloon p { font-size: clamp(7px, 2.6cqw, 10px); }
.balloon-progress { font-size: clamp(7px, 2.4cqw, 9px); }
.balloon.cleared .balloon-body { pointer-events: none; }
.quiet-copy strong { font-size: 6cqw; }
.tool-tray { padding: 3cqw; font-size: clamp(9px, 2.8cqw, 11px); }
.tool-tray .tray-step { display: none; }
.feedback { min-height: 62px; padding: 10px 12px; }
.feedback p { font-size: 10px; }
.finish h2 { font-size: 6.8cqw; }

.scene-picker { display: grid; grid-template-columns: 1fr 1fr; gap: 7px; margin: 0 0 12px; }
.scene-picker button { min-height: 44px; border: 1px solid #aabbb1; border-radius: 12px; background: #fbfbf4; color: #344c47; font-size: 12px; }
.scene-picker button[aria-pressed="true"] { border-color: #20353d; background: #20353d; color: #fffdf6; }
.scene-picker p { grid-column: 1 / -1; margin: 0; color: #62716c; font-size: 9px; text-align: center; }
.game-bar { padding-block: 0; min-height: 44px; }
#scene-restart { min-height: 44px; padding: 8px 0 8px 10px; border: 0; background: none; color: #315b50; font-size: 10px; }
#guide-arrow { font-size: inherit; }

/* Coupons peel from left to right along a perforated line. The target button
   stays outside the clipped paper so a partial tear remains resumable. */
.coupon .balloon-body {
  border-radius: 8px;
  border-style: dashed;
  padding: 6cqw 5cqw;
  transform: none;
  animation: none;
  clip-path: inset(0 0 0 calc(var(--removed, 0) * 100%));
  transition: clip-path .08s linear;
}
.coupon .balloon-body:before { top: var(--tear-y); left: 0; width: 100%; height: 0; background: none; border-top: 2px dashed #9a684c; border-radius: 0; }
.coupon .balloon-body:after { content: '가상 쿠폰 · 실제 사용 불가'; position: absolute; bottom: 3cqw; left: 5cqw; color: #775f47; font-size: 2.5cqw; }
.coupon h2 { font-size: 9cqw; letter-spacing: -.5cqw; margin: 5cqw 0 3cqw; }
.coupon p { white-space: pre-line; font-size: 3cqw; line-height: 1.65; }
.coupon .balloon-progress { bottom: 3cqw; z-index: 1; }
.coupon .valve:before { top: 12px; left: 6px; width: 34px; height: 25px; border-radius: 5px; background: #f19654; }
.coupon .valve:after { content: '→'; transform: none; font-size: 22px; }
.coupon .valve.selected:before { box-shadow: 0 0 0 6px #fff9dcaa; }
.coupon.cleared .balloon-body { transform: none; clip-path: inset(0 0 0 100%); }
.stage[data-scene="coupons"] .quiet-scene { background: linear-gradient(#e9e6d4, #f6f1db); }
.stage[data-scene="coupons"] .tool.latched .grip { fill: #ffbd81; }
.stage[data-scene="coupons"] .tool-tray { justify-content: flex-start; }

@keyframes inflate {
  from { transform: scale(.82); opacity: .65; }
  to { transform: scale(1); opacity: 1; }
}

@media (max-height: 740px) {
  .shell { padding-top: 12px; }
  .page-header { margin-bottom: 14px; }
  .intro > p:last-child { margin-bottom: 12px; }
  .eyebrow { margin-bottom: 5px; }
  h1 { font-size: 23px; margin-bottom: 8px; }
  .game { width: min(100%, calc((100svh - 285px) * .580645)); }
  .scene-picker { margin-bottom: 8px; gap: 4px; }
}

@media (prefers-reduced-motion: reduce) {
  .balloon-body { animation: none; transition: none; }
}

