(() => {
  'use strict';
  const core = globalThis.PuffPuzzle;
  const byId = id => document.getElementById(id);
  const stage = byId('stage');
  const tool = byId('tool');
  const pieceRoot = byId('pieces');
  const pullButton = byId('pull');
  const guide = byId('pull-guide');
  const finish = byId('finish');
  let state = core.fresh();
  let capturedPointer = null;
  let previousAnnouncement = '';
  const elements = new Map();
  const toPoint = event => {
    const rect = stage.getBoundingClientRect();
    return { x: (event.clientX - rect.left) / rect.width * core.WIDTH, y: (event.clientY - rect.top) / rect.height * core.HEIGHT };
  };
  function announce(message) {
    if (message !== previousAnnouncement) {
      byId('status').textContent = message;
      previousAnnouncement = message;
    }
  }
  function buildPieces() {
    const scene = core.getScene(state.sceneId);
    pieceRoot.replaceChildren();
    elements.clear();
    for (const piece of scene.items) {
      const element = document.createElement('article');
      element.className = `balloon${piece.width < 220 ? ' balloon-small' : ''}${scene.kind === 'coupon' ? ' coupon' : ''}`;
      element.style.cssText = `left:${piece.x / core.WIDTH * 100}%;top:${piece.y / core.HEIGHT * 100}%;width:${piece.width / core.WIDTH * 100}%;height:${piece.height / core.HEIGHT * 100}%;--balloon:${piece.color};--valve-origin:${(piece.target.x - piece.x) / piece.width * 100}%;--tear-y:${(piece.target.y - piece.y) / piece.height * 100}%;`;
      // All copy is fixed local data, never user or network input.
      element.innerHTML = `<div class="balloon-body"><div class="balloon-topline"><span>${piece.label}</span><span class="badge">${piece.badge}</span></div><h2>${piece.title}</h2><p>${piece.copy}</p><span class="balloon-progress" hidden></span></div><button class="valve" type="button" aria-label="${piece.label} ${scene.targetName}. 선택해서 집게 끼우기."></button>`;
      const valve = element.querySelector('.valve');
      valve.style.left = `${(piece.target.x - piece.x) / piece.width * 100}%`;
      valve.style.top = `${(piece.target.y - piece.y) / piece.height * 100}%`;
      const isCurrent = () => state.sceneId === scene.id && elements.get(piece.id)?.element === element;
      valve.addEventListener('click', () => {
        if (!isCurrent()) return;
        state = core.select(state, piece.id);
        render();
        if (state.selected) pullButton.focus({ preventScroll: true });
      });
      element.querySelector('.balloon-body').addEventListener('click', () => {
        if (!isCurrent()) return;
        announce(scene.messages.body);
        element.classList.remove('wobble');
        void element.offsetWidth;
        element.classList.add('wobble');
      });
      pieceRoot.append(element);
      elements.set(piece.id, { element, valve, progress: element.querySelector('.balloon-progress') });
    }
  }
  function render() {
    const scene = core.getScene(state.sceneId);
    const completedBefore = !finish.hidden;
    for (const piece of state.pieces) {
      const node = elements.get(piece.id);
      const cleared = piece.progress >= 1;
      node.element.classList.toggle('cleared', cleared);
      node.element.style.setProperty('--air', 1 - piece.progress);
      node.element.style.setProperty('--removed', piece.progress);
      node.element.setAttribute('aria-hidden', String(cleared));
      node.valve.disabled = cleared;
      node.valve.classList.toggle('selected', state.selected === piece.id);
      node.valve.setAttribute('aria-pressed', String(state.selected === piece.id));
      node.progress.hidden = !piece.progress || cleared;
      node.progress.textContent = `${scene.progressName} ${Math.round((1 - piece.progress) * 100)}%`;
    }
    const count = state.pieces.filter(piece => piece.progress === 1).length;
    byId('counter').textContent = `정리 ${count} / ${state.pieces.length}`;
    tool.style.left = `${state.tool.x / core.WIDTH * 100}%`;
    tool.style.top = `${state.tool.y / core.HEIGHT * 100}%`;
    tool.classList.toggle('dragging', Boolean(state.drag));
    tool.classList.toggle('latched', Boolean(state.selected));
    tool.hidden = state.completed;
    pullButton.hidden = !state.selected || Boolean(state.drag) || state.completed;
    guide.classList.toggle('visible', Boolean(state.selected) && !state.completed);
    guide.style.left = `${Math.min(state.tool.x + 55, 316) / core.WIDTH * 100}%`;
    guide.style.top = `${Math.max(20, Math.min(state.tool.y + (scene.axis === 'x' ? -65 : 9), 542)) / core.HEIGHT * 100}%`;
    finish.hidden = !state.completed;
    const message = state.event === 'cleared' ? `후우! ${count}개 정리했어요. 다음 ${scene.targetName}를 찾아보세요.` : scene.messages[state.event];
    announce(state.completed ? scene.completeMessage : message);
    byId('feedback-icon').textContent = state.completed ? '✓' : state.selected ? scene.arrow : scene.approachArrow;
    if (state.completed && !completedBefore) byId('finish-title').focus({ preventScroll: true });
  }
  function releaseCapture() {
    // Relinquish ownership first: release may synchronously trigger loss events.
    const pointerId = capturedPointer;
    capturedPointer = null;
    if (pointerId !== null && tool.hasPointerCapture(pointerId)) {
      try { tool.releasePointerCapture(pointerId); }
      catch (error) { if (error.name !== 'NotFoundError') throw error; }
    }
  }
  function cancelInteraction() {
    if (!state.drag && !state.selected && capturedPointer === null) return;
    state = core.putDown(state);
    releaseCapture();
    render();
  }
  tool.addEventListener('pointerdown', event => {
    if (!event.isPrimary || event.button !== 0 || capturedPointer !== null) return;
    event.preventDefault();
    state = core.begin(state, toPoint(event), event.pointerId);
    if (!state.drag) return;
    capturedPointer = event.pointerId;
    try { tool.setPointerCapture(event.pointerId); }
    catch (error) {
      if (error.name !== 'NotFoundError' && error.name !== 'InvalidStateError') throw error;
      cancelInteraction();
      return;
    }
    tool.focus({ preventScroll: true });
    render();
  });
  tool.addEventListener('pointermove', event => {
    if (capturedPointer !== event.pointerId) return;
    if (event.buttons === 0 || event.clientX < 0 || event.clientY < 0 || event.clientX >= window.innerWidth || event.clientY >= window.innerHeight) {
      cancelInteraction();
      return;
    }
    state = core.move(state, toPoint(event), event.pointerId);
    if (!state.drag) releaseCapture();
    render();
  });
  const endPointer = event => {
    if (capturedPointer !== event.pointerId) return;
    state = core.end(state, event.pointerId);
    releaseCapture();
    render();
  };
  tool.addEventListener('pointerup', endPointer);
  tool.addEventListener('pointercancel', endPointer);
  tool.addEventListener('lostpointercapture', event => {
    if (capturedPointer !== event.pointerId) return;
    if (tool.hasPointerCapture(event.pointerId)) return;
    cancelInteraction();
  });
  tool.addEventListener('click', event => {
    // Pointer gestures already use pointerdown/move/up. Only keyboard or
    // assistive activation should select here; stale pointer clicks do nothing.
    if (event.detail !== 0) return;
    const next = state.pieces.find(piece => piece.progress < 1);
    if (next) state = core.select(state, next.id);
    render();
  });
  function pullOneStep() {
    const selectedBefore = state.selected;
    state = core.pull(state);
    render();
    if (selectedBefore && !state.selected && !state.completed) {
      const next = state.pieces.find(piece => piece.progress < 1);
      elements.get(next.id).valve.focus({ preventScroll: true });
    }
  }
  pullButton.addEventListener('click', pullOneStep);
  document.addEventListener('keydown', event => {
    if (event.key === 'Escape') {
      state = core.putDown(state);
      releaseCapture();
      render();
      if (!state.completed) tool.focus({ preventScroll: true });
    } else if (state.selected && !state.drag && stage.closest('.game').contains(document.activeElement) && (event.key === core.getScene(state.sceneId).arrowKey || event.key === ' ')) {
      event.preventDefault();
      pullOneStep();
    }
  });
  window.addEventListener('blur', cancelInteraction);
  window.addEventListener('pagehide', cancelInteraction);
  document.addEventListener('visibilitychange', () => {
    if (document.hidden) cancelInteraction();
  });
  document.addEventListener('pointerout', event => {
    if (event.relatedTarget === null && event.pointerId === capturedPointer) cancelInteraction();
  });
  function startScene(sceneId, focusTool = true) {
    state = core.fresh(sceneId);
    releaseCapture();
    const scene = core.getScene(state.sceneId);
    stage.setAttribute('data-scene', scene.id);
    byId('game').setAttribute('aria-label', `${scene.label} 퍼즐`);
    byId('edition').textContent = `작은 화면 정리 · ${scene.number}`;
    byId('scene-eyebrow').textContent = scene.eyebrow;
    byId('scene-action').textContent = scene.action;
    byId('tool-name').textContent = scene.toolName;
    tool.setAttribute('aria-label', `${scene.toolName}. 잡고 ${scene.targetName}로 끌어가세요. 끼운 뒤 ${scene.direction} 당기세요.`);
    byId('tray-target').textContent = `${scene.targetName}로 ${scene.approachArrow}`;
    byId('guide-arrow').textContent = scene.arrow;
    byId('guide-text').textContent = `${scene.direction} 쭉`;
    byId('finish-copy').textContent = scene.finishCopy;
    byId('restart').textContent = scene.restartLabel;
    byId('scene-restart').setAttribute('aria-label', `${scene.label} 처음부터 다시 시작`);
    pullButton.textContent = `${scene.arrow} 집게 한 칸 당기기`;
    byId('control-help').textContent = `${scene.targetName}를 누르면 집게가 끼워집니다. ‘집게 한 칸 당기기’를 네 번 누르거나, ${scene.arrow} / Space 키로 당기세요. Tab 키로 대상을 고를 수 있습니다. Esc 키로 집게를 내려놓습니다. 중간에 놓아도 진행은 유지됩니다. 장면 선택과 다시 시작은 해당 장면을 처음부터 엽니다.`;
    for (const option of Object.values(core.SCENES)) {
      byId(`scene-${option.id}`).setAttribute('aria-pressed', String(option.id === scene.id));
    }
    buildPieces();
    render();
    if (focusTool) tool.focus({ preventScroll: true });
  }
  byId('restart').addEventListener('click', () => startScene(state.sceneId));
  byId('scene-restart').addEventListener('click', () => startScene(state.sceneId));
  for (const scene of Object.values(core.SCENES)) {
    byId(`scene-${scene.id}`).addEventListener('click', () => startScene(scene.id));
  }
  startScene(core.DEFAULT_SCENE, false);
})();

