// Shared, DOM-free rules for both scenes. All positions use logical units.
(() => {
  'use strict';
  const WIDTH = 360;
  const HEIGHT = 620;
  const SNAP_RADIUS = 34;
  const SCENES = globalThis.PuffScenes;
  const DOCK = SCENES.balloons.dock;
  const DEFAULT_SCENE = 'balloons';
  const getScene = id => Object.hasOwn(SCENES, id) ? SCENES[id] : SCENES[DEFAULT_SCENE];
  const clamp = (value, min, max) => Math.max(min, Math.min(max, value));
  const validPoint = point => point && Number.isFinite(point.x) && Number.isFinite(point.y);
  const active = (state, id) => state.pieces.find(piece => piece.id === id && piece.progress < 1);
  const config = (state, id) => getScene(state.sceneId).items.find(piece => piece.id === id);
  const fresh = (sceneId = DEFAULT_SCENE) => {
    const scene = getScene(sceneId);
    return { sceneId: scene.id, pieces: scene.items.map(({ id }) => ({ id, progress: 0 })), tool: { ...scene.dock }, drag: null, selected: null, event: 'ready', completed: false };
  };
  function begin(state, point, pointerId = 1) {
    if (state.completed || state.drag || !validPoint(point)) return state;
    const selected = state.selected && active(state, state.selected);
    const axis = getScene(state.sceneId).axis;
    return { ...state, event: selected ? 'attached' : 'grabbed', drag: { pointerId, offsetX: point.x - state.tool.x, offsetY: point.y - state.tool.y, targetId: selected ? selected.id : null, anchor: state.tool[axis], toolBase: { ...state.tool }, startProgress: selected ? selected.progress : 0 } };
  }
  function updateProgress(state, id, progress, tool) {
    // Snap floating-point coordinate noise, never a visibly incomplete pull.
    const normalizedProgress = progress >= 1 - 1e-9 ? 1 : clamp(progress, 0, 1);
    const pieces = state.pieces.map(piece => piece.id === id ? { ...piece, progress: normalizedProgress } : piece);
    const cleared = pieces.find(piece => piece.id === id).progress === 1;
    return { ...state, pieces, tool: cleared ? { ...getScene(state.sceneId).dock } : tool, drag: cleared ? null : state.drag, selected: cleared ? null : id, event: cleared ? 'cleared' : 'progress', completed: pieces.every(piece => piece.progress === 1) };
  }
  function move(state, point, pointerId = 1) {
    const drag = state.drag;
    if (!drag || pointerId !== drag.pointerId || !validPoint(point)) return state;
    const scene = getScene(state.sceneId);
    const rawTool = { x: point.x - drag.offsetX, y: point.y - drag.offsetY };
    const tool = { x: clamp(rawTool.x, 18, WIDTH - 18), y: clamp(rawTool.y, 20, HEIGHT - 24) };
    if (drag.targetId) {
      const target = active(state, drag.targetId);
      if (!target) return state;
      const progress = Math.max(target.progress, drag.startProgress + Math.max(0, rawTool[scene.axis] - drag.anchor) / scene.pullDistance);
      const attachedTool = { ...drag.toolBase, [scene.axis]: drag.toolBase[scene.axis] + (progress - drag.startProgress) * scene.pullDistance };
      return updateProgress(state, target.id, progress, attachedTool);
    }
    const nearest = scene.items.filter(piece => active(state, piece.id))
      .map(piece => ({ piece, distance: Math.hypot(tool.x - piece.target.x, tool.y - piece.target.y) }))
      .sort((a, b) => a.distance - b.distance)[0];
    if (nearest && nearest.distance <= SNAP_RADIUS) {
      return { ...state, selected: nearest.piece.id, tool: { ...nearest.piece.target }, event: 'attached', drag: { ...drag, targetId: nearest.piece.id, anchor: tool[scene.axis], toolBase: { ...nearest.piece.target }, startProgress: active(state, nearest.piece.id).progress } };
    }
    return { ...state, tool, event: 'grabbed' };
  }
  function end(state, pointerId = 1) {
    if (!state.drag || state.drag.pointerId !== pointerId) return state;
    return { ...state, tool: { ...getScene(state.sceneId).dock }, selected: null, drag: null, event: state.drag.targetId ? 'paused' : 'miss' };
  }
  function select(state, id) {
    if (state.completed || state.drag || !active(state, id)) return state;
    return { ...state, selected: id, tool: { ...config(state, id).target }, event: 'attached' };
  }
  function pull(state, amount = .25) {
    const target = active(state, state.selected);
    if (!target || state.drag || !Number.isFinite(amount) || amount <= 0) return state;
    const scene = getScene(state.sceneId);
    const anchor = config(state, target.id).target;
    const progress = target.progress + amount;
    return updateProgress(state, target.id, progress, { ...anchor, [scene.axis]: anchor[scene.axis] + clamp(progress, 0, 1) * 50 });
  }
  function putDown(state) {
    if (state.completed) return state;
    return { ...state, tool: { ...getScene(state.sceneId).dock }, drag: null, selected: null, event: 'paused' };
  }
  globalThis.PuffPuzzle = Object.freeze({ WIDTH, HEIGHT, SNAP_RADIUS, DOCK, SCENES, DEFAULT_SCENE, getScene, fresh, begin, move, end, select, pull, putDown });
})();

