// Local scene content only. Shared input and progress rules live in puzzle.js.
(() => {
  'use strict';
  const freeze = value => {
    if (value && typeof value === 'object') {
      Object.values(value).forEach(freeze);
      Object.freeze(value);
    }
    return value;
  };
  globalThis.PuffScenes = freeze({
    balloons: {
      id: 'balloons', number: '01', label: '알림 풍선', kind: 'balloon', axis: 'y', arrowKey: 'ArrowDown', arrow: '↓', direction: '아래로', pullDistance: 78, dock: { x: 98, y: 565 },
      eyebrow: '부풀어 오른 알림, 공기를 빼볼까요?', action: '노란 밸브에 끼우고 ↓ 아래로', targetName: '노란 밸브', toolName: '공기 집게', approachArrow: '↗',
      progressName: '공기', restartLabel: '다시 부풀리기 ↺', finishCopy: '세 개의 알림에서 공기를 뺐어요.',
      completeMessage: '세 개의 알림을 모두 정리했어요. 다시 부풀리기로 재시작할 수 있어요.',
      messages: {
        ready: '파란 집게를 잡아 노란 밸브로 옮겨보세요.',
        grabbed: '노란 밸브 가까이 가져가면 집게가 끼워져요.',
        attached: '딸깍! 이제 집게를 아래로 쭉 당겨요. 소리 없이도 괜찮아요.',
        progress: '공기가 빠지고 있어요. 아래로 조금 더 당겨요.',
        paused: '빠진 공기는 그대로예요. 밸브에 다시 끼워 이어서 당겨요.',
        miss: '집게가 돌아왔어요. 노란 밸브 가까이 다시 가져가세요.',
        body: '풍선 몸통 대신 노란 밸브에 집게를 끼워요.',
      },
      items: [
