import test from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { runInNewContext } from 'node:vm';

// A deliberately small DOM/event fixture executes the actual app.js handlers.
// It does not render CSS or establish native browser/capture compatibility.
function createApp() {
  const read = name => readFileSync(new URL(`../${name}`, import.meta.url), 'utf8');
  let document;
  const deferred = [];
  class Element {
    constructor() {
      this.listeners = new Map();
      this.children = [];
      this.attributes = new Map();
      this.classes = new Set();
      this.style = { setProperty: (name, value) => { this.style[name] = String(value); } };
      this.hidden = false;
      this.disabled = false;
      this.captures = new Set();
      this.releaseCalls = 0;
      this.classList = {
        add: name => this.classes.add(name),
        remove: name => this.classes.delete(name),
        contains: name => this.classes.has(name),
        toggle: (name, force) => {
          const add = force ?? !this.classes.has(name);
          if (add) this.classes.add(name); else this.classes.delete(name);
          return add;
        },
      };
    }
    set className(value) { this.classes = new Set(value.split(/\s+/).filter(Boolean)); }
    set innerHTML(value) {
      // These are the three queried nodes in each generated balloon template.
      this.parts = {};
      for (const name of ['balloon-body', 'balloon-progress', 'valve']) {
        const child = new Element();
        child.className = name;
        child.hidden = name === 'balloon-progress';
        this.parts[`.${name}`] = child;
      }
      this.append(this.parts['.balloon-body'], this.parts['.valve']);
      this.parts['.balloon-body'].append(this.parts['.balloon-progress']);
      assert.match(value, /class="valve"/);
    }
    querySelector(selector) { return this.parts?.[selector] ?? null; }
    setAttribute(name, value) { this.attributes.set(name, value); }
    append(...children) { children.forEach(child => { child.parent = this; this.children.push(child); }); }
    replaceChildren(...children) { this.children.forEach(child => { child.parent = null; }); this.children = []; this.append(...children); }
    contains(child) { return child === this || this.children.some(node => node.contains(child)); }
    closest(selector) { return selector === '.game' && this.classes.has('game') ? this : this.parent?.closest(selector); }
    focus() { document.activeElement = this; }
    addEventListener(type, handler) {
      if (!this.listeners.has(type)) this.listeners.set(type, []);
      this.listeners.get(type).push(handler);
    }
    emit(type, properties = {}) {
      const event = { type, target: this, defaultPrevented: false, preventDefault() { this.defaultPrevented = true; }, ...properties };
      for (const handler of this.listeners.get(type) ?? []) handler(event);
      return event;
    }
    getBoundingClientRect() { return { left: 20, top: 80, width: 360, height: 620 }; }
    setPointerCapture(id) {
      if (this.captureFailure) { const error = new Error('Pointer already inactive'); error.name = 'NotFoundError'; throw error; }
      this.captures.add(id);
    }
    hasPointerCapture(id) { return this.captures.has(id); }
    releasePointerCapture(id) {
      this.releaseCalls++;
      if (!this.captures.delete(id)) return;
      const lost = () => this.emit('lostpointercapture', { pointerId: id });
      if (this.deferLost) deferred.push(lost); else lost();
    }
  }
  const nodes = new Map();
  for (const match of read('index.html').matchAll(/<[^>]+\bid="([^"]+)"[^>]*>/g)) {
    const node = new Element();
    node.hidden = /\shidden(?:\s|>)/.test(match[0]);
    node.className = /\bclass="([^"]*)"/.exec(match[0])?.[1] ?? '';
    nodes.set(match[1], node);
  }
  const get = id => {
    assert.ok(nodes.has(id), `index.html must contain #${id}`);
    return nodes.get(id);
  };
  document = new Element();
  document.getElementById = get;
  document.createElement = () => new Element();
  document.hidden = false;
  const game = get('game');
  game.append(get('stage'), get('pull'));
  get('stage').append(get('tool'), get('pieces'), get('pull-guide'), get('finish'));
  get('finish').append(get('finish-title'), get('restart'));
  const window = new Element();
  window.innerWidth = 900;
  window.innerHeight = 900;
  const context = { document, window };
  runInNewContext(`${read('src/scenes.js')}\n${read('src/puzzle.js')}\n${read('src/app.js')}`, context);
  const core = context.PuffPuzzle;
  const tool = get('tool');
  const currentScene = () => core.getScene(get('stage').attributes.get('data-scene'));
  const pointer = (type, point = currentScene().dock, extra = {}) => tool.emit(type, {
    pointerId: 7, isPrimary: true, button: 0, buttons: 1,
    clientX: point.x + 20, clientY: point.y + 80, ...extra,
  });
  const balloon = index => get('pieces').children[index];
  function halfPull(index = 0) {
    const scene = currentScene();
    const valve = scene.items[index].target;
    pointer('pointerdown');
    pointer('pointermove', valve);
    pointer('pointermove', { ...valve, [scene.axis]: valve[scene.axis] + scene.pullDistance / 2 });
    assert.equal(balloon(index).querySelector('.balloon-progress').textContent, `${scene.progressName} 50%`);
  }
  function clearRound(sceneId = 'balloons') {
    const scene = core.getScene(sceneId);
    const order = sceneId === 'balloons' ? [2, 0, 1] : [1, 0];
    for (const index of order) {
      const valve = scene.items[index].target;
      pointer('pointerdown');
      pointer('pointermove', valve);
      pointer('pointermove', { ...valve, [scene.axis]: valve[scene.axis] + scene.pullDistance });
      pointer('pointerup', valve, { buttons: 0 });
      // A browser may synthesize this click after the pointer gesture.
      tool.emit('click', { detail: 1 });
    }
    assert.equal(get('counter').textContent, `정리 ${scene.items.length} / ${scene.items.length}`);
    assert.equal(get('finish').hidden, false);
  }
  function assertDocked() {
    assert.equal(tool.hasPointerCapture(7), false);
    assert.equal(tool.classList.contains('dragging'), false);
    assert.equal(tool.classList.contains('latched'), false);
    assert.equal(get('pull-guide').classList.contains('visible'), false);
    assert.equal(get('pull').hidden, true);
    assert.equal(tool.style.left, `${currentScene().dock.x / core.WIDTH * 100}%`);
    assert.equal(tool.style.top, `${currentScene().dock.y / core.HEIGHT * 100}%`);
  }
  return { core, get, tool, window, document, balloon, pointer, halfPull, clearRound, assertDocked, flushLost: () => deferred.splice(0).forEach(fn => fn()) };
}

for (const sceneId of ['balloons', 'coupons']) {
 for (const reason of ['pointercancel', 'lostpointercapture', 'blur', 'hidden', 'pagehide', 'outside', 'released-outside', 'document-exit']) {
  test(`${sceneId} / ${reason}: cancel halfway, preserve progress, ignore stale movement, and grab again`, () => {
    const app = createApp();
    app.get(`scene-${sceneId}`).emit('click');
    const scene = app.core.getScene(sceneId);
    app.halfPull();
    const valve = scene.items[0].target;
    if (reason === 'pointercancel') app.pointer('pointercancel');
    if (reason === 'lostpointercapture') app.tool.releasePointerCapture(7);
    if (reason === 'blur') app.window.emit('blur');
    if (reason === 'hidden') { app.document.hidden = true; app.document.emit('visibilitychange'); }
    if (reason === 'pagehide') app.window.emit('pagehide');
    if (reason === 'outside') app.pointer('pointermove', valve, { clientX: -1 });
    if (reason === 'released-outside') app.pointer('pointermove', valve, { buttons: 0 });
    if (reason === 'document-exit') app.document.emit('pointerout', { pointerId: 7, relatedTarget: null });
    app.assertDocked();
    app.pointer('pointermove', { ...valve, [scene.axis]: valve[scene.axis] + scene.pullDistance });
    assert.equal(app.balloon(0).querySelector('.balloon-progress').textContent, `${scene.progressName} 50%`);
    app.document.hidden = false;
    app.pointer('pointerdown');
    app.pointer('pointermove', valve);
    app.pointer('pointermove', { ...valve, [scene.axis]: valve[scene.axis] + scene.pullDistance / 2 });
    assert.equal(app.get('counter').textContent, `정리 1 / ${scene.items.length}`);
  });
 }
}
test('backgrounding a keyboard-selected valve drops the tool and keeps partial air', () => {
  const app = createApp();
  app.balloon(0).querySelector('.valve').emit('click');
  app.get('pull').emit('click');
  app.document.hidden = true;
  app.document.emit('visibilitychange');
  app.assertDocked();
  assert.equal(app.balloon(0).querySelector('.balloon-progress').textContent, '공기 75%');
});
test('finishing a pull releases capture before hiding or relocating the tool', () => {
  const app = createApp();
  app.pointer('pointerdown');
  app.pointer('pointermove', app.core.SCENES.balloons.items[0].target);
  app.pointer('pointermove', { x: 239, y: 262 });
  app.assertDocked();
  assert.equal(app.tool.releaseCalls, 1);
});
test('capture failure rolls back the drag instead of stranding the next attempt', () => {
  const app = createApp();
  app.tool.captureFailure = true;
  assert.doesNotThrow(() => app.pointer('pointerdown'));
  app.assertDocked();
  app.tool.captureFailure = false;
  app.pointer('pointerdown');
  assert.equal(app.tool.hasPointerCapture(7), true);
});
test('reset during a drag discards progress, ignores old events, and restores fresh UI', () => {
  const app = createApp();
  app.tool.deferLost = true;
  app.balloon(0).querySelector('.balloon-body').emit('click');
  app.halfPull();
  app.get('scene-restart').emit('click');
  app.flushLost();
  app.pointer('pointermove', { x: 239, y: 400 });
  app.pointer('pointerup');
  app.tool.emit('click', { detail: 1 });
  app.assertDocked();
  assert.equal(app.get('counter').textContent, '정리 0 / 3');
  assert.equal(app.get('finish').hidden, true);
  assert.equal(app.document.activeElement, app.tool);
  for (let index = 0; index < 3; index++) {
    assert.equal(app.balloon(index).classList.contains('wobble'), false);
    assert.equal(app.balloon(index).querySelector('.valve').disabled, false);
    assert.equal(app.balloon(index).querySelector('.balloon-progress').hidden, true);
  }
  app.clearRound();
});
test('two complete rounds reset visuals, input ownership, focus, and control listeners', () => {
  const app = createApp();
  app.clearRound();
  assert.equal(app.document.activeElement, app.get('finish-title'));
  const listeners = [...app.tool.listeners].map(([type, handlers]) => [type, handlers.length]);
  app.get('restart').emit('click');
  app.assertDocked();
  assert.equal(app.tool.hidden, false);
  assert.equal(app.get('finish').hidden, true);
  assert.equal(app.document.activeElement, app.tool);
  app.tool.emit('click', { detail: 0 });
  app.document.emit('keydown', { key: 'ArrowDown' });
  assert.equal(app.balloon(0).querySelector('.balloon-progress').textContent, '공기 75%');
  app.document.emit('keydown', { key: 'Escape' });
  app.clearRound();
  assert.equal(app.document.activeElement, app.get('finish-title'));
  assert.deepEqual([...app.tool.listeners].map(([type, handlers]) => [type, handlers.length]), listeners);
});

test('selecting coupons updates objects, active scene, directions, counter, and help', () => {
  const app = createApp();
  app.get('scene-coupons').emit('click');
  assert.equal(app.get('pieces').children.length, 2);
  assert.ok(app.balloon(0).classList.contains('coupon'));
  assert.equal(app.get('counter').textContent, '정리 0 / 2');
  assert.equal(app.get('scene-coupons').attributes.get('aria-pressed'), 'true');
  assert.equal(app.get('scene-balloons').attributes.get('aria-pressed'), 'false');
  assert.equal(app.get('guide-arrow').textContent, '→');
  assert.equal(app.get('tool-name').textContent, '종이 집게');
  assert.match(app.get('scene-action').textContent, /오른쪽/);
  assert.match(app.get('control-help').textContent, /→/);
  app.balloon(0).querySelector('.balloon-body').emit('click');
  assert.match(app.get('status').textContent, /주황 탭/);
  assert.equal(app.get('counter').textContent, '정리 0 / 2');
  app.assertDocked();
});
test('coupon keyboard and tap controls use right arrow, not the balloon down arrow', () => {
  const app = createApp();
