  app.document.emit('keydown', { key: ' ' });
  assert.equal(app.balloon(0).querySelector('.balloon-progress').textContent, '남은 종이 50%');
  app.get('pull').emit('click');
  app.get('pull').emit('click');
  assert.equal(app.get('counter').textContent, '정리 1 / 2');
  assert.equal(app.document.activeElement, app.balloon(1).querySelector('.valve'));
});
test('switching during a drag drops old input and detached controls cannot affect the new scene', () => {
  const app = createApp();
