import test from 'node:test';
import assert from 'node:assert/strict';
import '../src/scenes.js';
import '../src/puzzle.js';

const game = globalThis.PuffPuzzle;
const coupons = game.SCENES.coupons;
const first = coupons.items[0];
const progress = state => state.pieces[0].progress;
const attach = (state, item = first) => game.move(game.begin(state, state.tool, 4), item.target, 4);

test('balloons remain the default; the coupon scene has its own two pieces and direction', () => {
  assert.equal(game.fresh().sceneId, 'balloons');
  assert.equal(game.fresh().pieces.length, 3);
  assert.equal(game.fresh('coupons').pieces.length, 2);
  assert.equal(coupons.axis, 'x');
  assert.equal(game.SCENES.balloons.axis, 'y');
  for (const unknown of ['missing', '__proto__', 'constructor']) assert.equal(game.fresh(unknown).sceneId, 'balloons');
});
test('a coupon requires contact followed by rightward motion; down and left do not tear', () => {
  let state = attach(game.fresh('coupons'));
  assert.equal(state.selected, first.id);
  assert.equal(progress(state), 0);
  state = game.move(state, { x: first.target.x, y: first.target.y + 180 }, 4);
  assert.equal(progress(state), 0);
  state = game.move(state, { x: first.target.x - 20, y: first.target.y }, 4);
  assert.equal(progress(state), 0);
  state = game.move(state, { x: first.target.x + 90, y: first.target.y }, 4);
  assert.equal(progress(state), .5);
  assert.equal(state.tool.x, first.target.x + 90);
  assert.equal(state.tool.y, first.target.y);
});
test('a partial coupon tear survives cancel and can be finished after reattachment', () => {
  let state = attach(game.fresh('coupons'));
  state = game.move(state, { x: first.target.x + 90, y: first.target.y }, 4);
  state = game.putDown(state);
  assert.equal(progress(state), .5);
  assert.deepEqual(state.tool, coupons.dock);
  state = attach(state);
  state = game.move(state, { x: first.target.x + 90, y: first.target.y }, 4);
  assert.equal(progress(state), 1);
  assert.equal(state.completed, false);
});
test('both coupons must be cleared and restarting their scene restores only coupons', () => {
  let state = game.fresh('coupons');
  for (const item of coupons.items) {
    state = attach(state, item);
    state = game.move(state, { x: item.target.x + coupons.pullDistance, y: item.target.y }, 4);
  }
  assert.equal(state.completed, true);
  assert.equal(game.begin(state, state.tool, 4), state);
  const restarted = game.fresh(state.sceneId);
  assert.equal(restarted.sceneId, 'coupons');
  assert.ok(restarted.pieces.every(piece => piece.progress === 0));
  assert.equal(restarted.pieces.length, 2);
});
test('scene changes do not reuse progress or accept another scene’s target IDs', () => {
  let balloonState = game.pull(game.select(game.fresh(), 'flash'));
  const couponState = game.fresh('coupons');
  assert.equal(game.select(couponState, 'flash'), couponState);
  assert.equal(game.select(balloonState, first.id), balloonState);
  assert.equal(progress(couponState), 0);
  assert.equal(progress(balloonState), .25);
  assert.equal(progress(game.fresh('balloons')), 0);
  assert.ok(Object.isFrozen(coupons.items[0].target));
});
test('coupon tap control uses the same progress and changes only its horizontal coordinate', () => {
  let state = game.select(game.fresh('coupons'), first.id);
  state = game.pull(state);
  assert.equal(progress(state), .25);
  assert.ok(state.tool.x > first.target.x);
  assert.equal(state.tool.y, first.target.y);
  for (let index = 0; index < 3; index++) state = game.pull(state);
  assert.equal(progress(state), 1);
  assert.deepEqual(state.tool, coupons.dock);
});
test('each scene has room for its pull and can approach either target from the dock', () => {
  for (const scene of Object.values(game.SCENES)) {
    const limit = scene.axis === 'x' ? game.WIDTH : game.HEIGHT;
    for (const item of scene.items) {
      assert.ok(item.target[scene.axis] + game.SNAP_RADIUS + scene.pullDistance < limit);
      let state = game.begin(game.fresh(scene.id), scene.dock, 4);
      // Sample an ordinary straight approach; another ad should not steal it.
      for (let step = 1; step <= 100 && !state.selected; step++) {
        state = game.move(state, {
          x: scene.dock.x + (item.target.x - scene.dock.x) * step / 100,
          y: scene.dock.y + (item.target.y - scene.dock.y) * step / 100,
        }, 4);
      }
      assert.equal(state.selected, item.id, `${scene.id}: ${item.id} is independently reachable`);
    }
  }
});
